# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the one place that turns DEFAULT_AI_MODEL (ds.util.const) into what an Agent gets,
#          and that knows what each provider needs: the Pydantic AI Gateway (a key) or a GitHub
#          Copilot seat (a token). Every agent in pkgs/ and services/ui is built with
#          ai_model().
# Usage: Agent(ai_model(), ...); credential_problem() -> "" or what to run; spend_tracked().
#        Change the model in one line: DEFAULT_AI_MODEL in pkgs/ds/util/const.py.
# ---------------------------------------------------------------------------
from __future__ import annotations

from typing import TYPE_CHECKING

from ds.settings import get_settings
from ds.util.const import DEFAULT_AI_MODEL

if TYPE_CHECKING:
    from pydantic_ai.models import Model

__all__ = ["CopilotTokenMissingError", "ai_model", "credential_problem", "model_label", "spend_tracked"]

GATEWAY_PREFIX = "gateway/"
COPILOT_PREFIX = "github-copilot:"
# Copilot serves these ids on its Responses endpoint only (its model list: GET /models,
# `supported_endpoints`); every other id is on chat completions
COPILOT_RESPONSES_PREFIXES = ("gpt-", "grok-")
_STORE_HINT = "run `ds settings sync`"


class CopilotTokenMissingError(RuntimeError):
    """A Copilot model was about to be called with no token stored."""


def _copilot_token() -> str:
    """The stored Copilot token, read when a request is sent (so a new `ds settings sync`
    applies without rebuilding the agents, and importing needs no token).
    """
    token = get_settings().github_copilot_token
    if token is None:
        raise CopilotTokenMissingError(f"no GitHub Copilot token is stored ({_STORE_HINT})")
    return token.get_secret_value()


async def _copilot_token_for_request() -> str:
    """_copilot_token in the shape the async OpenAI client calls before each request."""
    return _copilot_token()


def _copilot_model(model_id: str) -> Model:
    from pydantic_ai.models.github_copilot import (
        GitHubCopilotModel,  # pulls in openai: only for Copilot
    )
    from pydantic_ai.models.openai import OpenAIResponsesModel
    from pydantic_ai.providers.github_copilot import GitHubCopilotProvider

    # the provider sets up Copilot's URL and client headers; its client is then copied with the
    # token as a function, so nothing is read until a request goes out
    client = GitHubCopilotProvider(api_key="read-at-request-time").client.copy(api_key=_copilot_token_for_request)
    provider = GitHubCopilotProvider(openai_client=client)
    if model_id.startswith(COPILOT_RESPONSES_PREFIXES):
        return OpenAIResponsesModel(model_id, provider=provider)
    return GitHubCopilotModel(model_id, provider=provider)


def ai_model(name: str = DEFAULT_AI_MODEL) -> Model | str:
    """What Agent(...) gets for a model setting.

    'github-copilot:<id>' becomes a model object that needs no token until it is run; anything
    else (eg 'gateway/anthropic:claude-haiku-5-5') is passed through as written, for
    pydantic-ai to resolve at run time (agents use defer_model_check=True).
    """
    if name.startswith(COPILOT_PREFIX):
        return _copilot_model(name.removeprefix(COPILOT_PREFIX))
    return name


def credential_problem(name: str = DEFAULT_AI_MODEL) -> str:
    """Why the model can't be called on this machine ("" = it can): its key or token isn't
    stored.
    """
    settings = get_settings()
    if name.startswith(COPILOT_PREFIX) and settings.github_copilot_token is None:
        return f"no GitHub Copilot token is stored ({_STORE_HINT})"
    if name.startswith(GATEWAY_PREFIX) and settings.pydantic_project_api_key is None:
        return f"no AI key is stored ({_STORE_HINT})"
    return ""


def spend_tracked(name: str = DEFAULT_AI_MODEL) -> bool:
    """Whether the model's cost is known in dollars: only through the Gateway (Logfire's traces
    and the Gateway's limits). A Copilot seat bills premium requests, which nothing here reads.
    """
    return name.startswith(GATEWAY_PREFIX)


def model_label(name: str = DEFAULT_AI_MODEL) -> str:
    """The model alone, as shown to the user: 'gpt-5.6-luna', 'claude-haiku-5-5'."""
    return name.removeprefix(GATEWAY_PREFIX).partition(":")[2] or name
